package com.fixflow.mall.service;

import com.fixflow.mall.api.dto.CreateOrderRequest;
import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.repo.OrderRepository;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class OrderServiceTest {

    @Mock
    private OrderRepository orderRepository;

    @InjectMocks
    private OrderService orderService;

    private CreateOrderRequest validRequest;
    private MallOrder savedOrder;

    @BeforeEach
    void setUp() {
        validRequest = new CreateOrderRequest();
        validRequest.setUserId(100L);
        validRequest.setAmount(new BigDecimal("50.00"));
        validRequest.setItemIds(Arrays.asList(1L, 2L));

        savedOrder = new MallOrder();
        savedOrder.setId(1L);
        savedOrder.setUserId(100L);
        savedOrder.setAmount(new BigDecimal("50.00"));
        savedOrder.setItemIds(Arrays.asList(1L, 2L));
    }

    @Test
    @DisplayName("正向测试：正常金额应该成功创建订单")
    void createOrder_withValidAmount_shouldReturnSavedOrder() {
        when(orderRepository.save(any(MallOrder.class))).thenReturn(savedOrder);

        MallOrder result = orderService.createOrder(validRequest);

        assertNotNull(result);
        assertEquals(savedOrder.getId(), result.getId());
        assertEquals(savedOrder.getUserId(), result.getUserId());
        assertEquals(savedOrder.getAmount(), result.getAmount());
        assertEquals(savedOrder.getItemIds(), result.getItemIds());
        verify(orderRepository).save(any(MallOrder.class));
    }

    @Test
    @DisplayName("边界测试：金额为null应该抛出IllegalArgumentException而不是NullPointerException")
    void createOrder_withNullAmount_shouldThrowIllegalArgumentException() {
        CreateOrderRequest nullAmountRequest = new CreateOrderRequest();
        nullAmountRequest.setUserId(100L);
        nullAmountRequest.setAmount(null);
        nullAmountRequest.setItemIds(Arrays.asList(1L, 2L));

        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> orderService.createOrder(nullAmountRequest)
        );

        assertEquals("amount must > 0", exception.getMessage());
        verify(orderRepository, never()).save(any());
    }

    @Test
    @DisplayName("边界测试：金额为0应该抛出IllegalArgumentException")
    void createOrder_withZeroAmount_shouldThrowIllegalArgumentException() {
        CreateOrderRequest zeroAmountRequest = new CreateOrderRequest();
        zeroAmountRequest.setUserId(100L);
        zeroAmountRequest.setAmount(BigDecimal.ZERO);
        zeroAmountRequest.setItemIds(Arrays.asList(1L, 2L));

        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> orderService.createOrder(zeroAmountRequest)
        );

        assertEquals("amount must > 0", exception.getMessage());
        verify(orderRepository, never()).save(any());
    }

    @Test
    @DisplayName("边界测试：金额为负数应该抛出IllegalArgumentException")
    void createOrder_withNegativeAmount_shouldThrowIllegalArgumentException() {
        CreateOrderRequest negativeAmountRequest = new CreateOrderRequest();
        negativeAmountRequest.setUserId(100L);
        negativeAmountRequest.setAmount(new BigDecimal("-10.00"));
        negativeAmountRequest.setItemIds(Arrays.asList(1L, 2L));

        IllegalArgumentException exception = assertThrows(
                IllegalArgumentException.class,
                () -> orderService.createOrder(negativeAmountRequest)
        );

        assertEquals("amount must > 0", exception.getMessage());
        verify(orderRepository, never()).save(any());
    }

    @Test
    @DisplayName("验证金额为null时不再抛出NullPointerException")
    void createOrder_withNullAmount_shouldNotThrowNullPointerException() {
        CreateOrderRequest nullAmountRequest = new CreateOrderRequest();
        nullAmountRequest.setUserId(100L);
        nullAmountRequest.setAmount(null);
        nullAmountRequest.setItemIds(Arrays.asList(1L, 2L));

        assertDoesNotThrow(() -> {
            try {
                orderService.createOrder(nullAmountRequest);
            } catch (IllegalArgumentException e) {
                // Expected behavior - throw IllegalArgumentException instead of NullPointerException
                assertEquals("amount must > 0", e.getMessage());
            }
        });
    }
}
